function.arguments:
{
  "query": "Barcelona vs Real Madrid 2022/23 second  match La Liga"
}

{
  "database": "video_game_store",
  "collection": "Customers",
  "pipeline": [
    {
      "$match": {
        "Game Genre": "Sports",
        "Purchase Date": {
          "$gte": { "$date": "2023-02-01T00:00:00Z" },
          "$lt": { "$date": "2023-04-01T00:00:00Z" }
        }
      }
    },
    {
      "$addFields": {
        "Month Name": {
          "$switch": {
            "branches": [
              { "case": { "$eq": [{ "$month": "$Purchase Date" }, 2] }, "then": "February" },
              { "case": { "$eq": [{ "$month": "$Purchase Date" }, 3] }, "then": "March" }
            ],
            "default": "Other"
          }
        }
      }
    },
    {
      "$group": {
        "_id": "$Month Name",
        "total_spent": { "$sum": "$Purchase Amount" }
      }
    },
    {
      "$project": {
        "_id": 0,
        "month": "$_id",
        "total_spent": 1
      }
    },
    {
      "$group": {
        "_id": null,
        "months": {
          "$push": {
            "k": "$month",
            "v": "$total_spent"
          }
        }
      }
    },
    {
      "$replaceRoot": {
        "newRoot": {
          "$arrayToObject": "$months"
        }
      }
    },
    {
      "$project": {
        "February": 1,
        "March": 1,
        "percentage_change": {
          "$multiply": [
            {
              "$divide": [
                { "$subtract": ["$March", "$February"] },
                "$February"
              ]
            },
            100
          ]
        }
      }
    }
  ]
}

